 <div class="modal" id="intro"><section class="card"><div class="eyebrow">A FIRST-PERSON NIGHTMARE · 3 FLOORS</div><h1>HALL<br><span>PASS</span></h1><p>The school is locked. Somewhere in these halls are seven pieces of furry art—and a pizza-faced janitor with a broom who really hates visitors.</p><div class="instructions"><div><strong>WASD</strong> &nbsp; move</div><div><strong>MOUSE</strong> &nbsp; look around</div><div><strong>SHIFT</strong> &nbsp; sprint (but he hears)</div><div><strong>E</strong> &nbsp; take art / hide / stairs</div><div><strong>LOCKERS, DESKS, DOORS</strong> &nbsp; are safe places</div><div><strong>GOAL</strong> &nbsp; collect 7, escape downstairs</div></div><button class="start" id="start">ENTER THE SCHOOL →</button><span class="small">HEADPHONES RECOMMENDED · DON'T LET HIM GET CLOSE</span></section></div>
 <div class="modal" id="end" style="display:none"><section class="card"><div class="eyebrow" id="endKicker">BLACKWELL ACADEMY · 11:47 PM</div><h1 id="endTitle">YOU MADE<br><span>IT OUT.</span></h1><p id="endCopy">Seven pictures safe. One very angry janitor left behind. The night bus is still running.</p><button class="start" id="again">PLAY AGAIN →</button></section></div>
 </main>
 <script>
+const canvas=document.querySelector('#view'),ctx=canvas.getContext('2d',{alpha:false}),W=720,H=405,FOV=Math.PI*.37,TAU=Math.PI*2;
+const maps=[[
+'###############','#.....#.......#','#.....#.......#','#.............#','###.#######.###','#.............#','#.............#','#..###...###..#','#..#.......#..#','#..#.......#..#','#.............#','#.....#.......#','###############'],[
+'###############','#.....#.......#','#.............#','#..###...###..#','#..#.......#..#','#..#.......#..#','#.............#','###.#######.###','#.............#','#..###...###..#','#.............#','#.....#.......#','###############'],[
+'###############','#.......#.....#','#.......#.....#','#.............#','###.#######.###','#.............#','#..###...###..#','#..#.......#..#','#..#.......#..#','#.............#','#.......#.....#','#.......#.....#','###############']];
+const pics=[{f:0,x:4.5,y:2.5},{f:0,x:11.5,y:2.5},{f:1,x:2.5,y:5.5},{f:1,x:12.5,y:5.5},{f:1,x:4.5,y:10.5},{f:2,x:2.5,y:2.5},{f:2,x:12.5,y:10.5}].map((p,i)=>({...p,id:i,got:false,type:'picture'}));
+const hides=[{f:0,x:2.5,y:6.5,name:'under a classroom desk',kind:'desk'},{f:0,x:12.5,y:6.5,name:'inside a locker',kind:'locker'},{f:0,x:3.5,y:9.5,name:'behind a classroom door',kind:'door'}, {f:1,x:12.5,y:2.5,name:'inside a locker',kind:'locker'},{f:1,x:2.5,y:9.5,name:'under a classroom desk',kind:'desk'},{f:2,x:11.5,y:2.5,name:'behind a classroom door',kind:'door'},{f:2,x:4.5,y:8.5,name:'inside a locker',kind:'locker'}].map((p,i)=>({...p,id:'hide'+i,type:'hide'}));
+const stairs=[{x:7.5,y:10.5},{x:7.5,y:10.5},{x:7.5,y:10.5}];
+const deco=[];for(let f=0;f<3;f++){for(let x=1;x<14;x+=2)for(let y of [1,11])deco.push({f,x:x+.5,y:y+.5,type:'locker'});for(let x of [1,13])for(let y=3;y<10;y+=2)deco.push({f,x:x+.5,y:y+.5,type:'plant'});}
+let player={x:2.5,y:3.5,a:0,f:0},enemy={x:10.5,y:6.5,f:0,step:0,lastX:10.5,lastY:6.5,alert:0};
