function wall(f,x,y){const ix=Math.floor(x),iy=Math.floor(y);return !maps[f]||!maps[f][iy]||maps[f][iy][ix]!=='.';}
function clamp(v,a,b){return Math.max(a,Math.min(b,v))}function norm(a){while(a>Math.PI)a-=TAU;while(a<-Math.PI)a+=TAU;return a}function dist(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
function showToast(t){const el=$('#toast');el.textContent=t;el.classList.add('on');toastTimer=2.2}function refresh(){const got=pics.filter(p=>p.got).length;$('#collect').innerHTML=pics.map(p=>`<i class="pip ${p.got?'got':''}"></i>`).join('');$('#floorLabel').textContent=['GROUND FLOOR','SECOND FLOOR','THIRD FLOOR'][player.f];$('#stamina').textContent='▰'.repeat(Math.ceil(stamina/17))+'▱'.repeat(6-Math.ceil(stamina/17));$('#threat').textContent=enemy.alert>2?'● HE’S CLOSE':'● '+(enemy.alert>.3?'SOMETHING IS LISTENING':'QUIET HALLS')}
function nearby(){let candidates=[];for(const p of pics)if(!p.got&&p.f===player.f&&dist(player,p)<1.45)candidates.push({...p,label:'E  ·  TAKE THE FURRY PICTURE'});for(const h of hides)if(h.f===player.f&&dist(player,h)<1.25)candidates.push({...h,label:hidden?'E  ·  LEAVE '+h.name.toUpperCase():'E  ·  HIDE '+h.name.toUpperCase()});if(dist(player,stairs[player.f])<1.35)candidates.push({type:'stairs',label:player.f===0?'E  ·  CLIMB TO THE SECOND FLOOR':'E  ·  '+(player.f===1?'CLIMB TO THE THIRD FLOOR':'GO DOWN TO THE NEXT FLOOR')});if(player.f===0&&dist(player,{x:2.5,y:2.5})<1.5)candidates.push({type:'exit',label:pics.every(p=>p.got)?'E  ·  ESCAPE THE SCHOOL':'THE EXIT IS LOCKED · FIND ALL 7 PICTURES'});return candidates.sort((a,b)=>dist(player,a)-dist(player,b))[0]||null}
function interact(){if(dead||won||paused)return;if(hidden){hidden=false;hideObj=null;$('#hiddenText').style.display='none';showToast('You slip back into the hallway.');return}const n=nearest;if(!n)return;if(n.type==='picture'){n.got=true;showToast('PICTURE '+(pics.filter(p=>p.got).length)+' / 7  ·  TUCKED AWAY');enemy.alert=Math.max(enemy.alert,.5);refresh()}else if(n.type==='hide'){hidden=true;hideObj=n;$('#hiddenText').style.display='block';$('#prompt').style.display='none';showToast('You hide '+n.name+'. Stay quiet.');}else if(n.type==='stairs'){player.f=(player.f+1)%3;if(player.f===0&&n.label.includes('DOWN'))player.f=2;player.x=stairs[player.f].x;player.y=stairs[player.f].y;showToast(['Ground floor','Second floor','Third floor'][player.f]);enemy.alert=Math.max(enemy.alert,.6);refresh()}else if(n.type==='exit'){if(pics.every(p=>p.got)){finish(true)}else showToast('Still missing '+(7-pics.filter(p=>p.got).length)+' pictures. Keep looking.')}}
function finish(win){dead=!win;won=win;paused=true;$('#end').style.display='flex';$('#endKicker').textContent=win?'BLACKWELL ACADEMY · 11:47 PM':'BLACKWELL ACADEMY · INCIDENT REPORT';$('#endTitle').innerHTML=win?'YOU MADE<br><span>IT OUT.</span>':'CAUGHT<br><span>AFTER HOURS.</span>';$('#endCopy').textContent=win?'Seven pictures safe. One very angry janitor left behind. The night bus is still running.':'The broom taps once against the tile. The pizza was extra cheesy. Maybe the next run goes better.'}
function startGame(){started=true;paused=false;$('#intro').style.display='none';$('#end').style.display='none';hud.style.display='block';if(innerWidth>700&&canvas.requestPointerLock)canvas.requestPointerLock();last=performance.now();requestAnimationFrame(loop)}$('#start').onclick=startGame;$('#again').onclick=()=>{location.reload()};document.addEventListener('pointerlockchange',()=>hasMouse=document.pointerLockElement===canvas);canvas.addEventListener('click',()=>{if(started&&!paused&&innerWidth>700&&!hasMouse)canvas.requestPointerLock()});document.addEventListener('mousemove',e=>{if(hasMouse&&!hidden)player.a+=e.movementX*.0025});document.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.key.toLowerCase()==='e')interact();if(e.key==='Escape'&&started&&!won&&!dead){paused=!paused;if(paused)showToast('PAUSED · PRESS ESC TO RESUME');else last=performance.now()}});document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
document.querySelectorAll('.mobile-controls button').forEach(b=>{const key=b.dataset.key,action=b.dataset.action;b.addEventListener('pointerdown',e=>{e.preventDefault();if(key)keys[key]=true;if(action==='run')keys.shift=true;if(action==='interact')interact()});for(const ev of ['pointerup','pointerleave','pointercancel'])b.addEventListener(ev,()=>{if(key)keys[key]=false;if(action==='run')keys.shift=false})});

