function spriteCanvas(type,id=0){const c=document.createElement('canvas');c.width=80;c.height=112;const g=c.getContext('2d');g.imageSmoothingEnabled=false;
if(type==='picture'){const colors=[['#dfb781','#e8794e','#71b9ac'],['#bde3ce','#8774a9','#f2bd61'],['#d98d76','#799ed0','#d3c28d'],['#e7cb8f','#5b8d7b','#d17f80'],['#9c8ac4','#e7ba6a','#7ebcaf'],['#da9277','#8cb2c9','#ccb17b'],['#a8c596','#d57862','#7c78aa']][id];g.fillStyle='#59483a';g.fillRect(8,7,64,96);g.fillStyle='#bc9b6b';g.fillRect(12,11,56,88);g.fillStyle='#262b2c';g.fillRect(16,15,48,80);g.fillStyle=colors[0];g.beginPath();g.ellipse(40,54,18,24,0,0,TAU);g.fill();g.fillStyle=colors[1];g.beginPath();g.moveTo(25,39);g.lineTo(22,20);g.lineTo(36,34);g.fill();g.beginPath();g.moveTo(43,34);g.lineTo(59,19);g.lineTo(56,42);g.fill();g.fillStyle=colors[2];g.beginPath();g.ellipse(34,54,3,4,0,0,TAU);g.ellipse(47,54,3,4,0,0,TAU);g.fill();g.fillStyle='#161b1b';g.fillRect(32,64,17,3);g.fillStyle=colors[2];g.fillRect(23,81,34,10);g.fillStyle='#e7d8bd';g.font='6px monospace';g.fillText('AFTER HOURS',19,96);
}else if(type==='enemy'){g.fillStyle='#111';g.beginPath();g.ellipse(40,105,24,6,0,0,TAU);g.fill();g.fillStyle='#332322';g.fillRect(20,66,40,37);g.fillStyle='#d2a27d';g.fillRect(26,35,28,38);g.fillStyle='#d9b38a';g.beginPath();g.arc(40,37,19,0,TAU);g.fill();g.fillStyle='#ca3427';g.beginPath();g.moveTo(22,30);g.lineTo(26,12);g.lineTo(37,20);g.lineTo(50,9);g.lineTo(59,30);g.fill();g.fillStyle='#f6d582';g.beginPath();g.arc(40,36,14,0,TAU);g.fill();g.fillStyle='#c13b2e';for(const [x,y] of [[32,29],[46,26],[37,44],[49,39]]){g.beginPath();g.arc(x,y,2,0,TAU);g.fill()}g.fillStyle='#181513';g.fillRect(31,35,4,4);g.fillRect(45,35,4,4);g.fillStyle='#311a17';g.fillRect(36,45,10,3);g.fillStyle='#e4d7c0';g.fillRect(17,61,46,8);g.fillStyle='#73503a';g.save();g.translate(63,65);g.rotate(-.27);g.fillRect(-2,0,4,48);g.fillStyle='#a48e67';g.fillRect(-8,0,16,5);g.restore();g.fillStyle='#e7e2d4';g.fillRect(27,98,10,10);g.fillRect(44,98,10,10);
